import { z } from "zod";

// Row ids are uuids (TASK-007 decision). z.uuid() is Zod 4's strict RFC form (BP-006).
export const uuidSchema = z.uuid();
export const questionIdSchema = uuidSchema;
export const testIdSchema = uuidSchema;

// Short option ids such as "a", unique within one question and generated by the API
// (TASK-008 decision). True/false uses the fixed ids "true" and "false".
export const optionIdSchema = z.string().regex(/^[a-z]{1,5}$/, "Must be a short option id.");
export type OptionId = z.infer<typeof optionIdSchema>;

// The stable key of one question inside a published snapshot. The publish service (TASK-016)
// generates it; students send it back with each answer.
export const snapshotQuestionKeySchema = z
  .string()
  .regex(/^[A-Za-z0-9_-]{1,32}$/, "Must be a question key.");
export type SnapshotQuestionKey = z.infer<typeof snapshotQuestionKeySchema>;
